window.TADABBUR_JATHIYA = {"_meta":{"description":"تدبّر سورة الجاثية (٤٥) — سورةٌ مكّيّةٌ من الحواميم. تُسمّى الجاثيةَ لقوله «وترى كل أمة جاثية». محورُها الاستدلالُ بآياتِ الله في الآفاقِ والأنفس، والوعيدُ للأفّاكِ الأثيمِ المستكبرِ عن آيات الله، وبيانُ أنّ الله خلق السماواتِ والأرضَ بالحقِّ لتُجزى كلُّ نفسٍ بما كسبت، وذمُّ مَنِ اتّخذ إلهه هواه، وإنكارُ الدهريّين للبعث، ومشهدُ الأممِ جاثيةً يومَ القيامةِ تُدعى إلى كتابها. فيها «إن في السماوات والأرض لآيات للمؤمنين»، و«ويل لكل أفاك أثيم»، و«أفرأيت من اتخذ إلهه هواه»، و«وما يهلكنا إلا الدهر»، و«وترى كل أمة جاثية».","honesty":"كلُّ وقفةٍ مُسنَدةٌ إلى تفسيرٍ معتمد (ابن كثير/السعدي) وموسومةٌ بدرجتها. حالُ القلبِ والعملُ اجتهاديٌّ موسوم. لا يُقدَّم شيءٌ على أنه إعجازٌ مثبت."},"n":45,"name":"الجاثية","total_ayahs":37,"audio":[1,3,7,13,15,23,24,28,36,37],"passages":[{"title":"آياتُ الله في الآفاقِ والأنفسِ الدالّةُ عليه","range":[1,6],"theme":"افتتاحُ السورةِ بتنزيلِ الكتابِ من العزيزِ الحكيم، والاستدلالِ بآياتِ الله في السماواتِ والأرضِ وخلقِ الإنسانِ والدوابِّ واختلافِ الليلِ والنهارِ وإحياءِ الأرضِ بالمطر، وأنها آياتٌ للمؤمنين الموقنين العاقلين، فبأيِّ حديثٍ بعد الله وآياته يؤمنون","verses":[{"n":1,"reflection":{"text":"«حم» — حروفٌ مقطّعةٌ افتُتِحت بها السورة، من المتشابهِ الذي استأثر الله بعلمه، ويُشار بها إلى إعجازِ القرآن؛ ففي هذا تعظيمُ القرآن؛ فسلّم لله فيما استأثر بعلمه، وتدبّر ما بيّنه، فالتسليمُ فيما لم تعلم من صفاتِ الراسخين.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التسليمُ لله فيما استأثر بعلمه، والتدبّرُ لما بيّن."},"action":{"text":"اعلم أنّ سورةَ الجاثيةِ افتُتِحت بـ«حم» من الحروفِ المقطّعةِ التي هي من المتشابهِ الذي استأثر الله بعلمِ المرادِ منه؛ وأصحُّ ما قيل فيها الإشارةُ إلى إعجازِ القرآن المؤلَّفِ من جنسِ هذه الحروف؛ فسلّم لما استأثر الله بعلمه من المتشابه؛ وتدبّر واعمل بما بيّنه لك من المحكم؛ فالراسخون في العلمِ يقولون آمنّا به كلٌّ من عند ربنا؛ فاجعل تسليمك لله فيما لم تعلم علامةَ إيمانك؛ فبالتسليمِ والعملِ تُنال الهداية."}},{"n":2,"reflection":{"text":"«تنزيل الكتاب من الله العزيز الحكيم» — هذا القرآنُ تنزيلٌ من الله العزيزِ الغالبِ الحكيمِ في خلقه وشرعه؛ ففي هذا بيانُ مصدرِ القرآنِ وعظمته؛ فعظّم القرآنَ المنزَّلَ من الله العزيزِ الحكيم، فهو كلامُ العزيزِ الذي لا يُغالَب، الحكيمِ الذي يضع الأمورَ مواضعها، فاتّبعه وحكّمه في حياتك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ القرآنِ المنزَّلِ من العزيزِ الحكيم، وتحكيمُه."},"action":{"text":"تأمّل بيانَ مصدرِ القرآن: هذا القرآنُ تنزيلٌ من الله العزيزِ الذي لا يُغالَب ولا يُمانَع، الحكيمِ الذي يضع الأشياءَ مواضعها بحكمته في خلقه وأمره «تنزيل الكتاب من الله العزيز الحكيم»؛ ففي هذا بيانُ أنّ القرآنَ منزَّلٌ من الله ذي العزّةِ والحكمة؛ فهو كلامُ الله لا كلامَ البشر؛ فعظّم القرآنَ المنزَّلَ من الله العزيزِ الحكيم؛ فهو كلامُ العزيزِ الذي لا يُغالَب، الحكيمِ الذي أحكم آياته؛ فمن عرف أنّ القرآنَ من عند الله العزيزِ الحكيمِ عظّمه واتّبعه؛ فاتّبع القرآنَ وحكّمه في حياتك كلِّها؛ ولا تقدّم عليه قولَ أحد؛ فمن حكّم القرآنَ في حياته اهتدى وسعد؛ فاجعل القرآنَ إمامك وحكمك؛ فبتعظيمِه والعملِ به تُنال السعادة."}},{"n":3,"reflection":{"text":"«إن في السماوات والأرض لآيات للمؤمنين» — إنّ في خلقِ السماواتِ والأرضِ لدلالاتٍ على وحدانيةِ الله وقدرته للمؤمنين؛ ففي هذا الاستدلالُ بالآفاقِ على الخالق؛ فتأمّل آياتِ الله في السماواتِ والأرض، فبها يزداد إيمانك، فالكونُ كلُّه آياتٌ دالّةٌ على الله، فتفكّر فيها لتزداد يقينًا.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التفكّرُ في آياتِ الله الكونيةِ لزيادةِ الإيمان."},"action":{"text":"تأمّل الاستدلالَ بالكونِ على الخالق: إنّ في خلقِ السماواتِ العظيمةِ وما فيها من الشمسِ والقمرِ والنجوم، والأرضِ وما فيها من الجبالِ والبحارِ والأنهار، لآياتٍ ودلالاتٍ عظيمةً على وحدانيةِ الله وقدرتِه وحكمته، ينتفع بها المؤمنون «إن في السماوات والأرض لآيات للمؤمنين»؛ ففي هذا الاستدلالُ بآياتِ الله في الآفاقِ على وجودِه ووحدانيتِه؛ فالسماواتُ والأرضُ وما فيهما آياتٌ دالّةٌ على الله؛ لكنّ المؤمنين هم المنتفعون بها؛ فتأمّل آياتِ الله في السماواتِ والأرض؛ فبها يزداد إيمانك ويقينك بالله؛ سنريهم آياتنا في الآفاقِ وفي أنفسهم؛ فالكونُ كلُّه آياتٌ ناطقةٌ بوحدانيةِ الله وقدرته؛ فتفكّر فيها لتزداد يقينًا وإيمانًا؛ فمن تفكّر في خلقِ الله ازداد إيمانًا، ومن أعرض بقي في غفلته؛ فاجعل النظرَ في آياتِ الله عبادةً تزيدك إيمانًا؛ فبالتفكّرِ في الكونِ تعرف عظمةَ الخالقِ فتعبده حقَّ عبادته."}},{"n":4,"reflection":{"text":"«وفي خلقكم وما يبث من دابة آيات لقوم يوقنون» — وفي خلقِكم وما ينشر من الدوابِّ آياتٌ لأهلِ اليقين؛ ففي هذا الاستدلالُ بالأنفسِ والأحياء؛ فتأمّل آياتِ الله في خلقك وفي الدواب، فأنت آيةٌ ناطقة، فتفكّر في نفسك وفي خلقِ الله لتوقن بربّك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التفكّرُ في النفسِ وخلقِ الأحياءِ للوصولِ إلى اليقين."},"action":{"text":"تأمّل الاستدلالَ بالأنفسِ والأحياء: وفي خلقِكم أيها الناسُ من نطفةٍ ثم علقةٍ ثم مضغةٍ حتى صرتم بشرًا سويًّا، وما يبثُّ وينشر الله في الأرضِ من دابّةٍ على اختلافِ أنواعها وأشكالها ومنافعها، آياتٌ ودلالاتٌ على الخالقِ لقومٍ يوقنون «وفي خلقكم وما يبث من دابة آيات لقوم يوقنون»؛ ففي هذا الاستدلالُ بخلقِ الإنسانِ والدوابِّ على قدرةِ الله ووحدانيته؛ فأنت آيةٌ في نفسك، والدوابُّ آياتٌ في تنوّعها؛ فتأمّل آياتِ الله في خلقك: في سمعك وبصرك وعقلك وأعضائك؛ وفي أنفسكم أفلا تبصرون؛ وتأمّل خلقَ الدوابِّ وتنوّعها ومنافعها؛ أفلا ينظرون إلى الإبلِ كيف خُلِقت؛ فأنت وما حولك من الأحياءِ آياتٌ ناطقةٌ بعظمةِ الخالق؛ فتفكّر في نفسك وفي خلقِ الله لتصل إلى اليقينِ الجازمِ بربّك؛ فمن تفكّر في خلقِ نفسه والأحياءِ أيقن بالخالق؛ فاجعل تفكّرك في آياتِ الله سبيلًا لليقين؛ فباليقينِ تعبد الله كأنك تراه."}},{"n":5,"reflection":{"text":"«واختلاف الليل والنهار وما أنزل الله من السماء من رزق فأحيا به الأرض... آيات لقوم يعقلون» — وفي تعاقبِ الليلِ والنهار، وإنزالِ المطرِ فإحياءِ الأرض، وتصريفِ الرياح، آياتٌ لأهلِ العقول؛ ففي هذا الاستدلالُ بالظواهرِ الكونية؛ فأعمل عقلك في آياتِ الله المتجدّدة، فبها تعرف قدرةَ الله على البعث، فتفكّر لتعقل عن الله آياته.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إعمالُ العقلِ في آياتِ الله المتجدّدةِ لإدراكِ قدرته."},"action":{"text":"تأمّل الاستدلالَ بالظواهرِ الكونيةِ المتجدّدة: وفي اختلافِ الليلِ والنهارِ وتعاقبهما بالطولِ والقصرِ والضياءِ والظلام، وما أنزل الله من السماءِ من رزقٍ — وهو المطرُ — فأحيا به الأرضَ بعد موتها فأنبتت الزرعَ والثمار، وتصريفِ الرياحِ شمالًا وجنوبًا وحارّةً وباردة، آياتٌ ودلالاتٌ لقومٍ يعقلون ويتدبّرون «واختلاف الليل والنهار... آيات لقوم يعقلون»؛ ففي هذا الاستدلالُ بالظواهرِ الكونيةِ المتجدّدةِ على قدرةِ الله ووحدانيته والبعث؛ فتعاقبُ الليلِ والنهار، وإحياءُ الأرضِ بالمطر، وتصريفُ الرياح، آياتٌ عظيمة؛ وإحياءُ الأرضِ الميتةِ دليلٌ على إحياءِ الموتى؛ كذلك النشور؛ فأعمل عقلك في آياتِ الله المتجدّدة؛ فبها تعرف قدرةَ الله على كلِّ شيء، وعلى البعثِ والنشور؛ ومن آياته يريكم البرقَ خوفًا وطمعًا وينزّل من السماءِ ماءً فيحيي به الأرضَ بعد موتها؛ فتفكّر في هذه الآياتِ لتعقل عن الله عظمته وقدرته؛ فمن أعمل عقله في آياتِ الله اهتدى، ومن عطّله ضلّ؛ فاجعل عقلك في خدمةِ الإيمانِ بالتفكّرِ في آياتِ الله."}},{"n":6,"reflection":{"text":"«تلك آيات الله نتلوها عليك بالحق فبأي حديث بعد الله وآياته يؤمنون» — تلك آياتُ الله نقصّها عليك بالصدقِ والحق، فبأيِّ كلامٍ بعد كلامِ الله وآياته يؤمنون؟ ففي هذا تعظيمُ القرآنِ وتوبيخُ المعرضين؛ فآمن بآياتِ الله واكتفِ بها، فلا حديثَ أصدقُ من حديثِ الله، فاجعل القرآنَ حسبك ومصدرَ هدايتك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاكتفاءُ بآياتِ الله والإيمانُ بها، وتعظيمُ حديثه."},"action":{"text":"تأمّل تعظيمَ القرآنِ وتوبيخَ المعرضين: تلك آياتُ الله الدالّةُ على وحدانيتِه وقدرته، نتلوها ونقصّها عليك — يا محمدُ — بالحقِّ والصدق؛ فبأيِّ حديثٍ وكلامٍ بعد كلامِ الله وآياتِه الواضحةِ يؤمنون إن لم يؤمنوا بها؟ «تلك آيات الله نتلوها عليك بالحق فبأي حديث بعد الله وآياته يؤمنون»؛ ففي هذا تعظيمُ آياتِ الله وتوبيخُ من أعرض عنها؛ فإذا لم يؤمنوا بكلامِ الله وآياته، فبأيِّ حديثٍ يؤمنون؟ فلا حديثَ أصدقُ من حديثِ الله؛ ومن أصدقُ من الله حديثًا؛ ومن أصدقُ من الله قيلًا؛ فآمن أنت بآياتِ الله واكتفِ بها؛ فلا كلامَ أعظمُ ولا أصدقُ من كلامِ الله؛ فاجعل القرآنَ حسبك ومصدرَ هدايتك وتشريعك؛ ولا تلتفت إلى ما يخالفه من أقوالِ الناسِ وأهوائهم؛ فمن اكتفى بكلامِ الله وآياته اهتدى، ومن أعرض عنها إلى غيرها ضلّ؛ فاجعل القرآنَ إمامك؛ فبالإيمانِ به والعملِ بمقتضاه تُنال الهداية."}}]},{"title":"وعيدُ الأفّاكِ الأثيمِ المستكبرِ عن آيات الله","range":[7,11],"theme":"الويلُ لكلِّ أفّاكٍ أثيمٍ يسمع آياتِ الله ثم يصرُّ مستكبرًا كأن لم يسمعها ويتّخذها هزوًا، لهم عذابٌ مهينٌ ومن ورائهم جهنّمُ لا يُغني عنهم ما كسبوا ولا آلهتهم، وأنّ هذا القرآنَ هدًى والكافرون به لهم عذابٌ أليم","verses":[{"n":7,"reflection":{"text":"«ويل لكل أفاك أثيم» — ويلٌ وهلاكٌ لكلِّ كذّابٍ كثيرِ الآثام؛ ففي هذا الوعيدُ للكذّابِ الأثيم؛ فاحذر الكذبَ والإثمَ اللذين يورثان الويلَ والهلاك، فاصدق واجتنب الآثام، فالإفكُ والإثمُ من صفاتِ أهلِ الويل.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اجتنابُ الكذبِ والآثام، والصدقُ في القولِ والعمل."},"action":{"text":"تأمّل الوعيدَ للأفّاكِ الأثيم: ويلٌ — وهو الهلاكُ والعذابُ الشديد، أو وادٍ في جهنّم — لكلِّ أفّاكٍ كذّابٍ يفتري الكذبَ على الله وعلى الناس، أثيمٍ كثيرِ الآثامِ والذنوب «ويل لكل أفاك أثيم»؛ ففي هذا الوعيدُ الشديدُ للكذّابِ المفتري الأثيمِ المصرِّ على الذنوب؛ فجمع بين الكذبِ والإثم، فاستحقّ الويلَ والهلاك؛ فاحذر الكذبَ والافتراءَ على الله والناس؛ واحذر الإثمَ والإصرارَ على الذنوب؛ فإنهما يورثان الويلَ والهلاك؛ فالإفكُ والإثمُ من صفاتِ أهلِ الويلِ والعذاب؛ فاصدق في قولك وعملك؛ واجتنب الآثامَ صغيرها وكبيرها؛ إنّ الصدقَ يهدي إلى البرِّ والبرَّ يهدي إلى الجنّة؛ وإنّ الكذبَ يهدي إلى الفجورِ والفجورَ يهدي إلى النار؛ فمن صدق واجتنب الآثامَ نجا، ومن كذب وأثم هلك؛ فاجعل الصدقَ شعارك واجتنابَ الآثامِ ديدنك؛ فبالصدقِ والتقوى تنجو من الويلِ والهلاك."}},{"n":8,"reflection":{"text":"«يسمع آيات الله تتلى عليه ثم يصر مستكبرا كأن لم يسمعها فبشره بعذاب أليم» — يسمع آياتِ الله تُقرأ عليه ثم يصرُّ على كفره مستكبرًا كأنه لم يسمعها، فبشّره بعذابٍ أليم؛ ففي هذا ذمُّ الإصرارِ والاستكبارِ عن الحق؛ فاحذر الإصرارَ والاستكبارَ عند سماعِ آياتِ الله، فاسمعها بقلبٍ خاشعٍ منقاد، فالاستكبارُ عن الحقِّ يورث العذاب.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الخشوعُ عند سماعِ آياتِ الله، وتركُ الإصرارِ والاستكبار."},"action":{"text":"تأمّل ذمَّ المستكبرِ المصرّ: يسمع هذا الأفّاكُ الأثيمُ آياتِ الله تُتلى عليه واضحةً بيّنة، ثم يصرُّ على كفره وباطله مستكبرًا متعاظمًا عن الحق، كأنه لم يسمعها لعدمِ انتفاعه بها؛ فبشّره — على سبيلِ التهكّم — بعذابٍ أليمٍ موجع «يسمع آيات الله تتلى عليه ثم يصر مستكبرا كأن لم يسمعها فبشره بعذاب أليم»؛ ففي هذا ذمُّ الإصرارِ على الكفرِ والاستكبارِ عن الحقِّ بعد سماعِ آياتِ الله؛ فسمع الآياتِ لكنه أصرّ واستكبر ولم ينتفع؛ فاحذر الإصرارَ على الباطلِ والاستكبارَ عن الحقِّ عند سماعِ آياتِ الله؛ فاسمع آياتِ الله بقلبٍ خاشعٍ منقادٍ متدبّرٍ منتفع؛ الذين إذا ذُكِر الله وجلت قلوبهم؛ وإذا تُليت عليهم آياته زادتهم إيمانًا؛ ولا تكن كمن يسمعها ثم يصرُّ مستكبرًا كأن لم يسمعها؛ فالاستكبارُ عن الحقِّ والإصرارُ على الباطلِ يورث العذابَ الأليم؛ فمن خشع لآياتِ الله وانقاد لها اهتدى، ومن استكبر وأصرّ عُذّب؛ فاجعل قلبك خاشعًا منقادًا لآياتِ الله؛ فبالخشوعِ والانقيادِ تُنال الهداية، وبالاستكبارِ والإصرارِ يقع العذاب."}},{"n":9,"reflection":{"text":"«وإذا علم من آياتنا شيئا اتخذها هزوا أولئك لهم عذاب مهين» — وإذا علم شيئًا من آياتنا اتّخذها سخريةً واستهزاءً، أولئك لهم عذابٌ مذلّ؛ ففي هذا ذمُّ الاستهزاءِ بآياتِ الله؛ فاحذر الاستهزاءَ بشيءٍ من آياتِ الله، فعظّمها ووقّرها، فالاستهزاءُ بها يورث العذابَ المهين.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ آياتِ الله وتوقيرها، وتركُ الاستهزاءِ بها."},"action":{"text":"تأمّل ذمَّ المستهزئِ بآياتِ الله: وإذا علم هذا الأفّاكُ شيئًا من آياتنا وبلغه اتّخذها هزوًا وسخريةً واستهزاءً، لا يوقّرها ولا يعظّمها؛ أولئك المستهزئون لهم عذابٌ مهينٌ مذلٌّ جزاءَ استهزائهم واستكبارهم «وإذا علم من آياتنا شيئا اتخذها هزوا أولئك لهم عذاب مهين»؛ ففي هذا ذمُّ الاستهزاءِ بآياتِ الله والسخريةِ منها؛ فبدل أن يعظّمها ويتّبعها، اتّخذها هزوًا؛ فاحذر الاستهزاءَ بشيءٍ من آياتِ الله وشرعه ودينه؛ فعظّم آياتِ الله ووقّرها واتّبعها؛ ومن يعظّم شعائرَ الله فإنها من تقوى القلوب؛ ولئن سألتهم ليقولنّ إنما كنا نخوض ونلعب، قل أبالله وآياته ورسوله كنتم تستهزئون، لا تعتذروا قد كفرتم بعد إيمانكم؛ فالاستهزاءُ بآياتِ الله كفرٌ يورث العذابَ المهين؛ فمن عظّم آياتِ الله نجا وأُكرِم، ومن استهزأ بها عُذّب وأُهين؛ فاجعل تعظيمَ آياتِ الله في قلبك؛ فبتعظيمها تُكرَم، وبالاستهزاءِ بها تُهان؛ فاحذر أشدَّ الحذرِ من الاستهزاءِ بشيءٍ من دينِ الله."}},{"n":10,"reflection":{"text":"«من ورائهم جهنم ولا يغني عنهم ما كسبوا شيئا ولا ما اتخذوا من دون الله أولياء ولهم عذاب عظيم» — أمامهم جهنّمُ تنتظرهم، ولا ينفعهم ما كسبوا من مالٍ ولا آلهةٌ اتّخذوها من دونِ الله، ولهم عذابٌ عظيم؛ ففي هذا بيانُ عاقبةِ المستهزئين؛ فاحذر أن يكون أمامك جهنّمُ فلا ينفعك مالٌ ولا وليّ، فاعمل لما ينفعك، فالمالُ والأولياءُ لا يُغنيان يومَ القيامة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ لما ينفعُ يومَ القيامة، وإدراكُ أنّ المالَ والأولياءَ لا يُغنيان."},"action":{"text":"تأمّل عاقبةَ المستكبرين المستهزئين: من ورائهم وأمامهم جهنّمُ تنتظرهم، لا مفرَّ لهم منها؛ ولا يُغني عنهم ما كسبوا في الدنيا من الأموالِ والأولادِ والجاهِ شيئًا، ولا يُغني عنهم ما اتّخذوا من دونِ الله من الآلهةِ والأولياءِ التي عبدوها؛ ولهم عذابٌ عظيمٌ في جهنّم «من ورائهم جهنم ولا يغني عنهم ما كسبوا شيئا ولا ما اتخذوا من دون الله أولياء ولهم عذاب عظيم»؛ ففي هذا بيانُ عاقبةِ المستهزئين بآياتِ الله: جهنّمُ أمامهم، لا ينفعهم مالٌ ولا وليّ؛ فما كسبوه من الدنيا لا يدفع عنهم العذاب؛ وما عبدوه من دونِ الله لا يشفع لهم ولا ينصرهم؛ يومَ لا ينفع مالٌ ولا بنون؛ فاحذر أن يكون أمامك جهنّمُ فلا ينفعك مالٌ جمعته ولا وليٌّ اتّخذته من دونِ الله؛ فاعمل لما ينفعك يومَ القيامةِ من الإيمانِ والعملِ الصالح؛ فالمالُ والأولادُ والأولياءُ من دونِ الله لا يُغنون عنك شيئًا يومئذٍ؛ فمن اعتمد على الله وعمل صالحًا نجا، ومن اعتمد على مالِه وأوليائه خاب؛ فاجعل اعتمادك على الله وعملك الصالح؛ فبهما تنجو من جهنّمَ وعذابها العظيم."}},{"n":11,"reflection":{"text":"«هذا هدى والذين كفروا بآيات ربهم لهم عذاب من رجز أليم» — هذا القرآنُ هدًى، والذين كفروا بآياتِ ربّهم لهم عذابٌ من أسوإِ العذابِ وأشدِّه أليم؛ ففي هذا بيانُ أنّ القرآنَ هدًى، ووعيدُ الكافرين به؛ فاهتدِ بالقرآنِ واتّبعه، فهو الهدى، فالكفرُ بآياتِ الله يورث أشدَّ العذاب، فاجعل القرآنَ هاديك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاهتداءُ بالقرآنِ واتّباعُه، والحذرُ من الكفرِ بآياتِ الله."},"action":{"text":"تأمّل بيانَ أنّ القرآنَ هدًى ووعيدَ الكافرين: هذا القرآنُ هدًى كاملٌ يهدي إلى الحقِّ والصراطِ المستقيم؛ والذين كفروا بآياتِ ربّهم وجحدوها لهم عذابٌ من رجزٍ — وهو أسوأُ العذابِ وأشدُّه — أليمٌ موجع «هذا هدى والذين كفروا بآيات ربهم لهم عذاب من رجز أليم»؛ ففي هذا بيانُ أنّ القرآنَ هدًى للمتّبعين، ووعيدٌ شديدٌ للكافرين به؛ فمن اتّبعه اهتدى، ومن كفر به عُذّب أشدَّ العذاب؛ فاهتدِ أنت بالقرآنِ واتّبعه؛ فهو الهدى إلى الحقِّ والنور؛ قد جاءكم من الله نورٌ وكتابٌ مبين؛ إنّ هذا القرآنَ يهدي للتي هي أقوم؛ فاجعل القرآنَ هاديك وإمامك؛ واحذر الكفرَ بآياتِ الله والإعراضَ عنها؛ فالكفرُ بآياتِ الله يورث أشدَّ العذابِ وأليمه؛ فمن اهتدى بالقرآنِ نجا وسعد، ومن كفر به عُذّب وشقي؛ فاجعل القرآنَ هاديك في ظلماتِ الحياة؛ فبالاهتداءِ به تُنال السعادةُ في الدارين."}}]},{"title":"تسخيرُ الكونِ للإنسان، والأمرُ بالعفوِ والعمل","range":[12,15],"theme":"بيانُ نعمةِ تسخيرِ البحرِ والسفنِ وكلِّ ما في السماواتِ والأرضِ للإنسانِ ليشكر، وأمرُ المؤمنين بالعفوِ والصفحِ عمّن لا يرجون أيامَ الله، وأنّ العملَ الصالحَ للنفسِ والإساءةَ عليها ثم إلى الله الرجوع","verses":[{"n":12,"reflection":{"text":"«الله الذي سخر لكم البحر لتجري الفلك فيه بأمره ولتبتغوا من فضله ولعلكم تشكرون» — الله الذي ذلّل لكم البحرَ لتجريَ فيه السفنُ بأمره، ولتطلبوا من رزقه، ولعلّكم تشكرون؛ ففي هذا بيانُ نعمةِ تسخيرِ البحرِ والحثُّ على الشكر؛ فاشكر الله على تسخيرِ البحرِ والسفنِ ورزقه، فالنعمُ تستوجب الشكر، فاجعل شكرك بالطاعةِ واستعمالِ النعمِ في مرضاته.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ الله على نعمةِ تسخيرِ البحرِ ورزقه، بالطاعة."},"action":{"text":"تأمّل نعمةَ تسخيرِ البحر: الله وحده هو الذي سخّر وذلّل لكم البحرَ العظيمَ لتجريَ فيه السفنُ والفلكُ بأمره وتيسيره، فتحمل أثقالكم وتجاراتكم؛ ولتبتغوا وتطلبوا من فضلِ الله ورزقه بالتجارةِ والصيدِ واستخراجِ اللؤلؤِ والمرجان؛ ولعلّكم تشكرون الله على هذه النعم «الله الذي سخر لكم البحر لتجري الفلك فيه بأمره ولتبتغوا من فضله ولعلكم تشكرون»؛ ففي هذا بيانُ نعمةِ تسخيرِ البحرِ للناس، والحثُّ على شكرِ الله عليها؛ فسخّر الله البحرَ لتجريَ فيه السفنُ وتُطلَب منه الأرزاق؛ فاشكر الله على تسخيرِ البحرِ والسفنِ والرزقِ الذي يخرج منه؛ فالنعمُ العظيمةُ تستوجب الشكرَ العظيم؛ وترى الفلكَ مواخرَ فيه ولتبتغوا من فضله ولعلّكم تشكرون؛ فاجعل شكرك لله بالقلبِ اعترافًا، وباللسانِ ثناءً، وبالجوارحِ طاعةً؛ واستعمل النعمَ في طاعةِ الله لا في معصيته؛ فمن شكر النعمةَ زاده الله منها، ومن كفرها سلبها؛ لئن شكرتم لأزيدنّكم؛ فاجعل من كلِّ نعمةٍ سببًا لشكرِ الله وطاعته."}},{"n":13,"reflection":{"text":"«وسخر لكم ما في السماوات وما في الأرض جميعا منه إن في ذلك لآيات لقوم يتفكرون» — وسخّر لكم كلَّ ما في السماواتِ والأرضِ نعمةً منه، إنّ في ذلك لآياتٍ لقومٍ يتفكّرون؛ ففي هذا بيانُ عمومِ تسخيرِ الله للكونِ لخدمةِ الإنسان؛ فتفكّر في تسخيرِ الله لكلِّ شيءٍ لخدمتك، فاشكره على ذلك، فعمومُ التسخيرِ يوجب عمومَ الشكرِ والعبادة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التفكّرُ في عمومِ تسخيرِ الله، وشكرُه على ذلك."},"action":{"text":"تأمّل عمومَ تسخيرِ الله للكون: وسخّر لكم — أيها الناس — كلَّ ما في السماواتِ من شمسٍ وقمرٍ ونجومٍ وسحاب، وكلَّ ما في الأرضِ من دوابَّ وأشجارٍ وأنهارٍ وجمادات، جميعًا نعمةً وتفضّلًا منه سبحانه؛ إنّ في ذلك التسخيرِ العظيمِ لآياتٍ ودلالاتٍ على قدرةِ الله ورحمته لقومٍ يتفكّرون «وسخر لكم ما في السماوات وما في الأرض جميعا منه إن في ذلك لآيات لقوم يتفكرون»؛ ففي هذا بيانُ عمومِ تسخيرِ الله لكلِّ ما في الكونِ لخدمةِ الإنسانِ ومنفعته؛ فكلُّ ما في السماواتِ والأرضِ مسخّرٌ لك بنعمةِ الله؛ ألم تروا أنّ الله سخّر لكم ما في السماواتِ وما في الأرضِ وأسبغ عليكم نعمه ظاهرةً وباطنة؛ فتفكّر في تسخيرِ الله لكلِّ شيءٍ لخدمتك ومنفعتك؛ فاشكر الله على هذا التسخيرِ العام؛ فعمومُ التسخيرِ يوجب عمومَ الشكرِ والعبادة؛ فمن تفكّر في نعمِ الله شكرها، ومن غفل عنها كفرها؛ فاجعل التفكّرَ في نعمِ الله سببًا لشكره وعبادته؛ فبالتفكّرِ والشكرِ تعرف قدرَ نعمِ الله فتعبده حقَّ عبادته."}},{"n":14,"reflection":{"text":"«قل للذين آمنوا يغفروا للذين لا يرجون أيام الله ليجزي قوما بما كانوا يكسبون» — قل للمؤمنين أن يعفوا ويصفحوا عن الذين لا يخافون أيامَ الله (وقائعه بالأمم)، ليجزيَ الله كلًّا بعمله؛ ففي هذا الأمرُ بالعفوِ والصفحِ عن المسيئين؛ فاعفُ واصفح عمّن أساء إليك من الجاهلين، فالعفوُ من صفاتِ المؤمنين، ودع جزاءهم لله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"العفوُ والصفحُ عن المسيئين، وتفويضُ جزائهم لله."},"action":{"text":"تأمّل الأمرَ بالعفوِ والصفح: قل — يا محمدُ — للذين آمنوا: يغفروا ويعفوا ويصفحوا عن الذين لا يرجون ولا يخافون أيامَ الله — أي وقائعه ونقماته بالأممِ المكذّبة — من المشركين الذين يؤذونهم؛ ليجزيَ الله كلَّ قومٍ بما كانوا يكسبون: المؤمنين بعفوهم وصبرهم، والكافرين بإساءتهم «قل للذين آمنوا يغفروا للذين لا يرجون أيام الله ليجزي قوما بما كانوا يكسبون»؛ ففي هذا الأمرُ للمؤمنين بالعفوِ والصفحِ عن المشركين المؤذين، وتفويضِ أمرهم إلى الله؛ فأمرهم بالحلمِ والصفحِ لا بالانتقام؛ فاعفُ أنت واصفح عمّن أساء إليك من الجاهلين المعرضين؛ فالعفوُ والصفحُ من صفاتِ المؤمنين وأخلاقهم؛ خذِ العفوَ وأمر بالعرفِ وأعرض عن الجاهلين؛ ولْيعفوا ولْيصفحوا ألا تحبّون أن يغفر الله لكم؛ وادفع بالتي هي أحسنُ فإذا الذي بينك وبينه عداوةٌ كأنه وليٌّ حميم؛ فدع جزاءَ المسيئين لله؛ فهو يجزي كلًّا بعمله؛ فمن عفا وصفح أجره الله وأعزّه، ومن انتقم لنفسه فوّت الأجر؛ فاجعل العفوَ والصفحَ خلقك مع الجاهلين؛ فبالعفوِ تنال أجرَ الله ومحبّته."}},{"n":15,"reflection":{"text":"«من عمل صالحا فلنفسه ومن أساء فعليها ثم إلى ربكم ترجعون» — من عمل صالحًا فنفعه لنفسه، ومن أساء فضرره عليها، ثم إلى ربّكم تُرجَعون للحساب؛ ففي هذا تقريرُ العدلِ وأنّ الجزاءَ على العمل؛ فاعمل الصالحاتِ فنفعها لك، واجتنب الإساءةَ فضررها عليك، فأنت تعمل لنفسك، فاختر لها الخير.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ الصالحُ للنفس، واجتنابُ الإساءةِ، والاستعدادُ للرجوع."},"action":{"text":"تأمّل تقريرَ العدلِ في الجزاء: من عمل عملًا صالحًا من طاعةِ الله فثوابه ونفعه لنفسه، لا يعود على الله منه شيء؛ ومن أساء وعمل سيّئًا فوبالُه وضرره على نفسه؛ ثم إلى ربّكم — لا إلى غيره — تُرجَعون جميعًا يومَ القيامةِ فيجازيكم بأعمالكم «من عمل صالحا فلنفسه ومن أساء فعليها ثم إلى ربكم ترجعون»؛ ففي هذا تقريرُ عدلِ الله، وأنّ الجزاءَ مبنيٌّ على العمل؛ فنفعُ الطاعةِ للعاملِ نفسه، وضررُ المعصيةِ على فاعلها؛ فاعمل الصالحاتِ فإنّ نفعها يعود إليك؛ إن أحسنتم أحسنتم لأنفسكم وإن أسأتم فلها؛ واجتنب الإساءةَ والمعاصي فإنّ ضررها عليك؛ ولا تزر وازرةٌ وزرَ أخرى؛ فأنت تعمل لنفسك خيرًا كان أو شرًّا؛ فاختر لنفسك الخيرَ والعملَ الصالح؛ واعلم أنك راجعٌ إلى ربّك للحساب؛ فاستعدّ لذلك الرجوعِ بالعملِ الصالح؛ فمن عمل صالحًا وجده، ومن أساء ندم؛ فاجعل عملك صالحًا خالصًا لله؛ فبالعملِ الصالحِ تنفع نفسك في الدنيا والآخرة."}}]},{"title":"نعمُ الله على بني إسرائيل، وجعلُ النبيِّ على شريعة","range":[16,20],"theme":"إيتاءُ بني إسرائيلَ الكتابَ والحكمَ والنبوةَ وتفضيلُهم، واختلافُهم بغيًا بعد العلم، وجعلُ النبيِّ على شريعةٍ يتّبعها لا أهواءَ الجاهلين، وأنّ الله وليُّ المتّقين، وأنّ القرآنَ بصائرُ وهدًى ورحمةٌ للموقنين","verses":[{"n":16,"reflection":{"text":"«ولقد آتينا بني إسرائيل الكتاب والحكم والنبوة ورزقناهم من الطيبات وفضلناهم على العالمين» — ولقد آتينا بني إسرائيلَ التوراةَ والفهمَ والنبوة، ورزقناهم من الطيّبات، وفضّلناهم على عالمي زمانهم؛ ففي هذا بيانُ نعمِ الله على بني إسرائيل؛ فاعتبر بنعمِ الله على من قبلك، واشكر نعمَ الله عليك، فالنعمُ إذا لم تُشكَر زالت، فاشكرها بالطاعة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ نعمِ الله بالطاعة، والاعتبارُ بمن أنعم عليهم قبلك."},"action":{"text":"تأمّل نعمَ الله على بني إسرائيل: ولقد آتينا بني إسرائيلَ الكتابَ — وهو التوراة — والحكمَ — وهو الفهمُ والقضاءُ بين الناس بالحق — والنبوةَ حيث كثر فيهم الأنبياء؛ ورزقناهم من الطيّباتِ من المطاعمِ والمشارب؛ وفضّلناهم على عالمي زمانهم بكثرةِ الأنبياءِ والكتبِ والنعم «ولقد آتينا بني إسرائيل الكتاب والحكم والنبوة ورزقناهم من الطيبات وفضلناهم على العالمين»؛ ففي هذا بيانُ نعمِ الله العظيمةِ على بني إسرائيل: الكتابُ والحكمُ والنبوةُ والرزقُ الطيّبُ والتفضيل؛ فأنعم الله عليهم بهذه النعمِ العظيمة؛ لكنهم لمّا لم يشكروها وبدّلوا سُلِبوها وحلّ بهم الذلّ؛ فاعتبر بنعمِ الله على من قبلك، وكيف زالت عنهم لمّا كفروها؛ واشكر نعمَ الله عليك من الإسلامِ والقرآنِ والنبيِّ الخاتم؛ فالنعمُ إذا لم تُشكَر زالت وصارت وبالًا؛ فاشكر نعمَ الله بالإيمانِ والطاعةِ والعملِ الصالح؛ فمن شكر النعمةَ دامت له وزادت، ومن كفرها زالت عنه؛ فاجعل شكرك لنعمِ الله بالطاعةِ لا بالمعصية؛ فبالشكرِ تدوم النعمُ وتزيد."}},{"n":17,"reflection":{"text":"«وآتيناهم بينات من الأمر فما اختلفوا إلا من بعد ما جاءهم العلم بغيا بينهم إن ربك يقضي بينهم يوم القيامة فيما كانوا فيه يختلفون» — وأعطيناهم حججًا واضحةً في أمرِ الدين، فما اختلفوا إلا بعد مجيءِ العلمِ بغيًا بينهم، إنّ ربّك يقضي بينهم يومَ القيامةِ فيما اختلفوا؛ ففي هذا ذمُّ الاختلافِ بعد العلمِ بغيًا؛ فاحذر الاختلافَ في الدينِ بغيًا وحسدًا بعد العلم، فالزم الجماعةَ والحقّ، فالاختلافُ بغيًا سببُ الهلاك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"لزومُ الحقِّ والجماعة، والحذرُ من الاختلافِ بغيًا بعد العلم."},"action":{"text":"تأمّل ذمَّ الاختلافِ بعد العلم: وآتينا بني إسرائيلَ بيّناتٍ وحججًا واضحةً من أمرِ الدين، تبيّن الحقَّ من الباطل؛ فما اختلفوا في الدينِ وتفرّقوا إلا من بعد ما جاءهم العلمُ الموجبُ للاجتماعِ والاتّفاق؛ وكان اختلافهم بغيًا وحسدًا وعدوانًا بينهم، لا عن جهل؛ إنّ ربّك يقضي بينهم يومَ القيامةِ فيما كانوا فيه يختلفون، فيجزي المحقَّ والمبطل «وآتيناهم بينات من الأمر فما اختلفوا إلا من بعد ما جاءهم العلم بغيا بينهم...»؛ ففي هذا ذمُّ الاختلافِ في الدينِ بعد قيامِ الحجّةِ ومجيءِ العلم، وأنّ سببه البغيُ والحسد؛ فاختلفوا بعد العلمِ بغيًا لا جهلًا؛ فاحذر الاختلافَ والتفرّقَ في الدينِ بغيًا وحسدًا بعد بلوغِ العلمِ والحق؛ ولا تكونوا كالذين تفرّقوا واختلفوا من بعد ما جاءهم البيّنات؛ واعتصموا بحبلِ الله جميعًا ولا تفرّقوا؛ فالزم الحقَّ والجماعةَ ولا تشذّ عنهما؛ ودع البغيَ والحسدَ اللذين يفرّقان الأمّة؛ فالاختلافُ بغيًا وحسدًا سببُ الهلاكِ والفشل؛ فمن لزم الحقَّ والجماعةَ نجا، ومن اختلف بغيًا هلك؛ فاجعل مرجعك عند الاختلافِ كتابَ الله وسنّةَ رسوله؛ فبهما يُحسَم النزاعُ ويُعرَف الحق."}},{"n":18,"reflection":{"text":"«ثم جعلناك على شريعة من الأمر فاتبعها ولا تتبع أهواء الذين لا يعلمون» — ثم جعلناك — يا محمدُ — على شريعةٍ واضحةٍ من أمرِ الدين فاتّبعها، ولا تتّبع أهواءَ الجاهلين؛ ففي هذا الأمرُ باتّباعِ الشريعةِ ونبذِ الأهواء؛ فاتّبع شريعةَ الله ولا تتّبع أهواءَ الناس، فالحقُّ في الشرعِ لا في الهوى، فاجعل الشرعَ حكمك لا هوى الناس.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اتّباعُ الشريعةِ ونبذُ أهواءِ الجاهلين، وتحكيمُ الشرع."},"action":{"text":"تأمّل الأمرَ باتّباعِ الشريعة: ثم جعلناك — يا محمدُ — على شريعةٍ ومنهاجٍ واضحٍ من أمرِ الدينِ الذي شرعه الله لعباده؛ فاتّبع هذه الشريعةَ واعمل بها، فإنها الحقُّ الموصلُ إلى الله؛ ولا تتّبع أهواءَ الذين لا يعلمون الحقَّ من المشركين والجهّال، فتضلَّ عن سبيلِ الله «ثم جعلناك على شريعة من الأمر فاتبعها ولا تتبع أهواء الذين لا يعلمون»؛ ففي هذا الأمرُ للنبيِّ وأمّته باتّباعِ الشريعةِ المحكمة، والنهيُ عن اتّباعِ أهواءِ الجهّال؛ فالطريقُ إمّا اتّباعُ الشرعِ أو اتّباعُ الهوى؛ فاتّبع أنت شريعةَ الله المحكمةَ الواضحة؛ واعمل بما أمرك الله به؛ ولا تتّبع أهواءَ الناسِ ورغباتهم المخالفةَ للشرع؛ فالحقُّ في اتّباعِ الشرعِ لا في اتّباعِ الهوى؛ ومن أضلُّ ممّن اتّبع هواه بغيرِ هدًى من الله؛ ولا تتّبعِ الهوى فيضلَّك عن سبيلِ الله؛ فاجعل الشريعةَ حكمك وإمامك، لا هوى الناسِ ورغباتهم؛ فمن اتّبع الشرعَ اهتدى، ومن اتّبع الهوى ضلّ؛ فالزم شريعةَ الله، ونابذ أهواءَ المخالفين؛ فبالاتّباعِ للشرعِ تُنال الهدايةُ والنجاة."}},{"n":19,"reflection":{"text":"«إنهم لن يغنوا عنك من الله شيئا وإن الظالمين بعضهم أولياء بعض والله ولي المتقين» — إنّ هؤلاء الجهّال لن يدفعوا عنك من عذابِ الله شيئًا إن اتّبعتهم، والظالمون بعضهم أنصارُ بعض، والله وليُّ المتّقين وناصرهم؛ ففي هذا بيانُ عاقبةِ موالاةِ الظالمين، وولايةِ الله للمتّقين؛ فاتّقِ الله لتكون في ولايته، ولا توالِ الظالمين، فولايةُ الله للمتّقين خيرٌ من كلِّ نصير.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التقوى لنيلِ ولايةِ الله، وتركُ موالاةِ الظالمين."},"action":{"text":"تأمّل بيانَ ولايةِ الله للمتّقين: إنّ هؤلاء المشركين الجهّال لن يغنوا عنك — يا محمدُ — من عذابِ الله شيئًا إن اتّبعت أهواءهم؛ وإنّ الظالمين بعضهم أولياءُ بعضٍ يتناصرون على الباطل؛ والله وحده وليُّ المتّقين ينصرهم ويحفظهم ويتولّى أمورهم «إنهم لن يغنوا عنك من الله شيئا وإن الظالمين بعضهم أولياء بعض والله ولي المتقين»؛ ففي هذا بيانُ أنّ الجهّالَ لا ينفعون متّبعهم، وأنّ الظالمين يتناصرون فيما بينهم، وأنّ ولايةَ الله خاصّةٌ بالمتّقين؛ فالكفّارُ والظالمون يوالي بعضهم بعضًا؛ لكنّ الله وليُّ المتّقين؛ فاتّقِ الله بفعلِ أوامره واجتنابِ نواهيه لتكون في ولايةِ الله وحفظه؛ الله وليُّ الذين آمنوا يخرجهم من الظلماتِ إلى النور؛ ولا توالِ الظالمين ولا تتّبع أهواءهم؛ فإنهم لا يُغنون عنك من الله شيئًا؛ فولايةُ الله للمتّقين خيرٌ من كلِّ نصيرٍ وناصر؛ فمن كان الله وليَّه فلا خوفَ عليه، ومن والى الظالمين خُذِل؛ فاجعل ولاءك لله ولأوليائه المتّقين؛ فبالتقوى تنال ولايةَ الله ونصره وحفظه."}},{"n":20,"reflection":{"text":"«هذا بصائر للناس وهدى ورحمة لقوم يوقنون» — هذا القرآنُ بصائرُ للناسِ يُبصِرون بها الحق، وهدًى ورحمةٌ لقومٍ يوقنون؛ ففي هذا بيانُ أنّ القرآنَ بصائرُ وهدًى ورحمة؛ فاستبصر بالقرآنِ واهتدِ به وارجُ رحمته، فهو نورٌ للقلوب، فاجعله بصيرتك وهداك ورحمتك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستبصارُ بالقرآنِ والاهتداءُ به ورجاءُ رحمته."},"action":{"text":"تأمّل بيانَ أنّ القرآنَ بصائرُ وهدًى ورحمة: هذا القرآنُ بصائرُ للناسِ عامّةً، يُبصِرون به طريقَ الحقِّ من الباطل، والهدى من الضلال؛ وهو هدًى ورحمةٌ خاصّةٌ لقومٍ يوقنون به ويعملون بمقتضاه؛ فينتفعون به هدايةً ورحمة «هذا بصائر للناس وهدى ورحمة لقوم يوقنون»؛ ففي هذا بيانُ أنّ القرآنَ بصائرُ يُبصَر بها الحق، وهدًى إلى الصراطِ المستقيم، ورحمةٌ لمن آمن به وأيقن؛ فهو نورٌ وبصيرةٌ وهدًى ورحمة؛ فاستبصر أنت بالقرآنِ فتُبصِر الحقَّ والباطل؛ قد جاءكم بصائرُ من ربّكم فمن أبصر فلنفسه؛ واهتدِ بالقرآنِ إلى الصراطِ المستقيم؛ وارجُ رحمةَ الله بالإيمانِ به والعملِ بمقتضاه؛ وننزّل من القرآنِ ما هو شفاءٌ ورحمةٌ للمؤمنين؛ فاجعل القرآنَ بصيرتك التي تُبصِر بها، وهداك الذي تسير عليه، ورحمتك التي ترجوها؛ فمن استبصر بالقرآنِ واهتدى به ورجا رحمته سعد، ومن أعرض عنه عمي وضلّ؛ فأقبل على القرآنِ مستبصرًا مهتديًا راجيًا رحمةَ الله."}}]},{"title":"عدلُ الله في التمييز، وحكمةُ الخلقِ للجزاء، وذمُّ عبادةِ الهوى","range":[21,23],"theme":"إبطالُ التسويةِ بين المسيءِ والمحسن، وأنّ الله خلق السماواتِ والأرضَ بالحقِّ لتُجزى كلُّ نفسٍ بما كسبت لا يُظلَمون، وذمُّ من اتّخذ إلهه هواه فأضلّه الله على علمٍ وختم على سمعه وقلبه وبصره","verses":[{"n":21,"reflection":{"text":"«أم حسب الذين اجترحوا السيئات أن نجعلهم كالذين آمنوا وعملوا الصالحات سواء محياهم ومماتهم ساء ما يحكمون» — أظنّ الذين اكتسبوا السيّئاتِ أن نجعلهم كالمؤمنين الصالحين سواءً في حياتهم ومماتهم؟ ساء حكمهم؛ ففي هذا إبطالُ التسويةِ بين المسيءِ والمحسن؛ فاعلم أنّ الله لا يسوّي بين المسيءِ والمحسن، فاعمل الصالحاتِ لتكون من المحسنين، فالتسويةُ بينهما ظلمٌ ينزّه الله عنه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ الصالحُ لتكون من المحسنين، وإدراكُ عدلِ الله في التمييز."},"action":{"text":"تأمّل إبطالَ التسويةِ بين المسيءِ والمحسن: أم ظنّ الذين اجترحوا واكتسبوا السيّئاتِ من الكفرِ والمعاصي أن نجعلهم كالذين آمنوا وعملوا الصالحاتِ، مستوين في المحيا والممات؟ أي في الدنيا والآخرة؟ ساء وقبح ما يحكمون به من هذه التسويةِ الظالمة «أم حسب الذين اجترحوا السيئات أن نجعلهم كالذين آمنوا وعملوا الصالحات سواء محياهم ومماتهم ساء ما يحكمون»؛ ففي هذا إبطالٌ لظنِّ الكفّارِ أن يُسوَّوا بالمؤمنين، وبيانُ أنّ ذلك حكمٌ سيّئٌ يتنزّه الله عنه؛ فحكمةُ الله وعدله يأبيان التسويةَ بين المسيءِ والمحسن؛ فاعلم أنّ الله لا يسوّي بين المؤمنِ والكافر، ولا بين المطيعِ والعاصي؛ أفنجعل المسلمين كالمجرمين، ما لكم كيف تحكمون؛ أم نجعل الذين آمنوا وعملوا الصالحاتِ كالمفسدين في الأرض، أم نجعل المتّقين كالفجّار؛ فاعمل الصالحاتِ لتكون من المحسنين الفائزين؛ ولا تكن من المسيئين الخاسرين؛ فالتسويةُ بين المسيءِ والمحسنِ ظلمٌ ينزّه الله عنه؛ فمن آمن وعمل صالحًا فاز، ومن أساء وأجرم خسر؛ فاجعل عملك عملَ المحسنين؛ فبالإيمانِ والعملِ الصالحِ تنال ما لا يناله المسيئون."}},{"n":22,"reflection":{"text":"«وخلق الله السماوات والأرض بالحق ولتجزى كل نفس بما كسبت وهم لا يظلمون» — وخلق الله السماواتِ والأرضَ بالحقِّ والحكمة، ولتُجزى كلُّ نفسٍ بما كسبت، وهم لا يُظلَمون؛ ففي هذا بيانُ حكمةِ الخلقِ والجزاءِ العادل؛ فاعلم أنّ الله خلق الكونَ للجزاءِ العادل، فاعمل عملًا صالحًا تُجزى به، فالجزاءُ بالعدلِ لا ظلمَ فيه، فقدّم لنفسك خيرًا.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ الصالحُ للجزاء، وإدراكُ أنّ الخلقَ بالحقِّ والعدل."},"action":{"text":"تأمّل حكمةَ الخلقِ والجزاءِ العادل: وخلق الله السماواتِ والأرضَ بالحقِّ والحكمة، لا عبثًا ولا باطلًا؛ ومن الحقِّ أن يُبعَث الخلقُ فتُجزى كلُّ نفسٍ بما كسبت من خيرٍ أو شر؛ وهم لا يُظلَمون: لا يُنقَص محسنٌ من حسناته، ولا يُزاد مسيءٌ في سيّئاته «وخلق الله السماوات والأرض بالحق ولتجزى كل نفس بما كسبت وهم لا يظلمون»؛ ففي هذا بيانُ أنّ الله خلق الكونَ بالحقِّ والحكمة، وأنّ من مقتضى ذلك الجزاءَ العادلَ لكلِّ نفس؛ فالخلقُ قائمٌ على الحقّ، والجزاءُ قائمٌ على العدل؛ فاعلم أنّ الله ما خلق الكونَ إلا بالحقِّ وللجزاء؛ فاعمل عملًا صالحًا تُجزى به خيرًا؛ فكلُّ نفسٍ تُجزى بما كسبت؛ من جاء بالحسنةِ فله عشرُ أمثالها، ومن جاء بالسيّئةِ فلا يُجزى إلا مثلها وهم لا يُظلَمون؛ فالجزاءُ بالعدلِ التامِّ لا ظلمَ فيه؛ إنّ الله لا يظلم مثقالَ ذرّة؛ فقدّم لنفسك عملًا صالحًا تُجزى به؛ فمن أحسن وُفِّي أجره، ومن أساء جُوزي بعدل؛ فاجعل عملك صالحًا لتنال الجزاءَ الحسن؛ فبالعملِ الصالحِ تُجزى خيرًا يومَ لا ظلمَ فيه."}},{"n":23,"reflection":{"text":"«أفرأيت من اتخذ إلهه هواه وأضله الله على علم وختم على سمعه وقلبه وجعل على بصره غشاوة فمن يهديه من بعد الله أفلا تذكرون» — أرأيت من جعل هواه إلهه يطيعه، فأضلّه الله على علمٍ منه باستحقاقه، وختم على سمعه وقلبه وأعمى بصره، فمن يهديه بعد إضلالِ الله؟ أفلا تتّعظون؟ ففي هذا ذمُّ اتّباعِ الهوى وعاقبتُه؛ فاحذر أن تجعل هواك إلهك تطيعه، فاتّبع الحقَّ لا الهوى، فاتّباعُ الهوى يورث الضلالَ والختمَ على القلب.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"مخالفةُ الهوى واتّباعُ الحق، والحذرُ من اتّخاذِ الهوى إلهًا."},"action":{"text":"تأمّل ذمَّ اتّباعِ الهوى: أفرأيت — يا محمدُ — حالَ من اتّخذ هواه إلهًا له، يطيعه في كلِّ ما يدعوه إليه، ويقدّمه على طاعةِ الله؟ فأضلّه الله على علمٍ منه سبحانه بأنه أهلٌ للضلال؛ وختم على سمعه فلا يسمع الحق، وعلى قلبه فلا يعقله، وجعل على بصره غشاوةً فلا يبصر الهدى؛ فمن يهديه من بعد إضلالِ الله له؟ لا أحد؛ أفلا تذكّرون وتتّعظون «أفرأيت من اتخذ إلهه هواه وأضله الله على علم...»؛ ففي هذا ذمُّ من جعل هواه إلهه، وبيانُ عاقبتِه: الضلالُ والختمُ على السمعِ والقلبِ والبصر؛ فاتّباعُ الهوى المطلقُ عبادةٌ له من دونِ الله؛ فاحذر أن تجعل هواك إلهك تطيعه وتقدّمه على أمرِ الله؛ ولا تتّبعِ الهوى فيضلّك عن سبيلِ الله؛ ومن أضلُّ ممّن اتّبع هواه بغيرِ هدًى من الله؛ فاتّبع الحقَّ والشرعَ لا الهوى والرغبة؛ فإنّ اتّباعَ الهوى يورث الضلالَ والطبعَ على القلب؛ وأمّا من خاف مقامَ ربّه ونهى النفسَ عن الهوى فإنّ الجنّةَ هي المأوى؛ فمن خالف هواه واتّبع الحقَّ اهتدى، ومن اتّبع هواه ضلّ؛ فاجعل الحقَّ إمامك، وخالف هواك إذا خالف أمرَ الله؛ فبمخالفةِ الهوى واتّباعِ الحقِّ تُنال الهداية."}}]},{"title":"إنكارُ الدهريّين للبعث، والردُّ بتقريرِ الإحياءِ والإماتة","range":[24,26],"theme":"مقالةُ الدهريّين «ما هي إلا حياتنا الدنيا... وما يهلكنا إلا الدهر» وأنها ظنٌّ لا علم، وتعنّتُهم بطلبِ إحياءِ الآباء، والردُّ عليهم بأنّ الله يحييكم ثم يميتكم ثم يجمعكم إلى يومِ القيامةِ لا ريبَ فيه","verses":[{"n":24,"reflection":{"text":"«وقالوا ما هي إلا حياتنا الدنيا نموت ونحيا وما يهلكنا إلا الدهر وما لهم بذلك من علم إن هم إلا يظنون» — قال الدهريّون: ما الحياةُ إلا الدنيا، نموت ونحيا وما يُهلِكنا إلا مرورُ الزمان، وما لهم بذلك علمٌ إن هم إلا يظنّون؛ ففي هذا إبطالُ إنكارِ البعثِ ونسبةِ الإهلاكِ للدهر؛ فاحذر إنكارَ البعثِ ونسبةَ الأفعالِ للدهرِ دون الله، فالله هو المحيي المميت، فأيقن بالبعثِ ولا تسبَّ الدهر.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بالبعثِ ونسبةُ الإحياءِ والإماتةِ لله وحده."},"action":{"text":"تأمّل إبطالَ مقالةِ الدهريّين: وقال المنكرون للبعثِ من الدهريّين: ما الحياةُ إلا حياتنا الدنيا، نموت نحن ويحيا أولادنا، أو يموت قومٌ ويولد آخرون، وما يُهلِكنا إلا مرورُ الأيامِ والليالي؛ نسبوا الإهلاكَ للدهرِ لا لله، وأنكروا البعث؛ وما لهم بذلك من علمٍ يقين، إن هم إلا يظنّون ظنًّا لا يُغني من الحقِّ شيئًا «وقالوا ما هي إلا حياتنا الدنيا نموت ونحيا وما يهلكنا إلا الدهر وما لهم بذلك من علم إن هم إلا يظنون»؛ ففي هذا حكايةُ إنكارِ الدهريّين للبعث، ونسبتِهم الإهلاكَ إلى الدهر، وأنّ ذلك ظنٌّ لا علم؛ فأنكروا الآخرةَ وزعموا أنّ الزمانَ هو المُهلِك؛ فاحذر إنكارَ البعثِ والآخرة؛ واحذر نسبةَ الأفعالِ والإهلاكِ إلى الدهرِ والزمانِ دون الله؛ فالله هو المحيي المميت، وهو مقلّبُ الليلِ والنهار؛ قال الله: يؤذيني ابنُ آدم، يسبُّ الدهر، وأنا الدهر، بيدي الأمر، أقلّب الليلَ والنهار؛ فلا تسبَّ الدهرَ فإنّ الله هو الدهر؛ فأيقن بالبعثِ والنشورِ والحساب؛ وانسب الإحياءَ والإماتةَ والتدبيرَ إلى الله وحده؛ فمن أيقن بالبعثِ استعدّ له، ومن أنكره غفل وخسر؛ فاجعل يقينك بالله وبالبعثِ راسخًا؛ فبالإيمانِ باليومِ الآخرِ تعمل للآخرة."}},{"n":25,"reflection":{"text":"«وإذا تتلى عليهم آياتنا بينات ما كان حجتهم إلا أن قالوا ائتوا بآبائنا إن كنتم صادقين» — وإذا تُقرأ عليهم آياتنا واضحاتٍ ما كان جوابهم إلا أن قالوا: أحيوا آباءنا إن كنتم صادقين في البعث؛ ففي هذا بيانُ عجزهم عن الحجّةِ ولجوئِهم للتعنّت؛ فاحذر معارضةَ الحقِّ بالتعنّتِ عند العجزِ عن ردّه، فاقبل الحقَّ ببرهانه، فطلبُ المحالِ تعنّتًا دليلُ العجزِ عن الحجّة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"قبولُ الحقِّ ببرهانه، وتركُ التعنّتِ عند العجز."},"action":{"text":"تأمّل بيانَ عجزِ المنكرين عن الحجّة: وإذا تُتلى على هؤلاء المنكرين آياتُنا واضحاتٍ بيّنات، تدلُّ على البعثِ والتوحيد، ما كان جوابهم وحجّتهم إلا التعنّتَ والمكابرة، فقالوا: ائتوا بآبائنا الأموات فأحيوهم إن كنتم صادقين في دعوى البعث «وإذا تتلى عليهم آياتنا بينات ما كان حجتهم إلا أن قالوا ائتوا بآبائنا إن كنتم صادقين»؛ ففي هذا بيانُ عجزِ المنكرين عن معارضةِ الحقِّ بحجّة، ولجوئِهم إلى التعنّتِ وطلبِ المحال؛ فلمّا عجزوا عن ردِّ الآياتِ البيّناتِ طلبوا إحياءَ آبائهم في الدنيا؛ وهذا تعنّتٌ لا حجّة؛ فليس البعثُ في الدنيا بل يومَ القيامة؛ فاحذر أنت معارضةَ الحقِّ بالتعنّتِ وطلبِ المحالِ عند العجزِ عن ردّه؛ فطلبُ المعجزاتِ تعنّتًا لا استرشادًا من صفاتِ المكذّبين؛ فاقبل الحقَّ ببرهانه ودليله؛ ولا تطلب ما ليس من شأنِ الحقِّ ولا تتعنّت؛ فطلبُ المحالِ تعنّتًا دليلُ العجزِ عن الحجّةِ والمكابرة؛ فمن طلب الحقَّ بصدقٍ اهتدى، ومن تعنّت وكابر ضلّ؛ فاجعل طلبك للحقِّ طلبَ استرشادٍ لا طلبَ تعجيزٍ وتعنّت."}},{"n":26,"reflection":{"text":"«قل الله يحييكم ثم يميتكم ثم يجمعكم إلى يوم القيامة لا ريب فيه ولكن أكثر الناس لا يعلمون» — قل: الله يحييكم ثم يميتكم ثم يجمعكم إلى يومِ القيامةِ الذي لا شكَّ فيه، ولكنّ أكثرَ الناسِ لا يعلمون؛ ففي هذا تقريرُ الإحياءِ والإماتةِ والبعث؛ فأيقن بأنّ الله يحيي ويميت ويجمع للحساب، فاستعدّ لذلك اليوم، فمن أحياك وأماتك قادرٌ على جمعك، فأيقن بالبعث.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بالإحياءِ والإماتةِ والبعث، والاستعدادُ ليومِ الجمع."},"action":{"text":"تأمّل تقريرَ البعث: قل — يا محمدُ — لهؤلاء المنكرين: الله وحده يحييكم في الدنيا بعد أن كنتم نطفًا، ثم يميتكم عند انقضاءِ آجالكم، ثم يجمعكم أحياءً إلى يومِ القيامةِ الذي لا ريبَ ولا شكَّ فيه، للحسابِ والجزاء؛ ولكنّ أكثرَ الناسِ لا يعلمون ذلك لجهلهم وغفلتهم وإعراضهم «قل الله يحييكم ثم يميتكم ثم يجمعكم إلى يوم القيامة لا ريب فيه ولكن أكثر الناس لا يعلمون»؛ ففي هذا تقريرُ أنّ الله هو المحيي المميتُ الباعثُ الجامعُ للخلق؛ فردَّ على الدهريّين بأنّ الإحياءَ والإماتةَ والبعثَ من الله؛ فالذي أحياكم من عدمٍ وأماتكم قادرٌ على جمعكم وبعثكم؛ فأيقن بأنّ الله يحيي ويميت ويجمع للحساب؛ كيف تكفرون بالله وكنتم أمواتًا فأحياكم ثم يميتكم ثم يحييكم ثم إليه تُرجَعون؛ فاستعدّ ليومِ القيامةِ الذي لا ريبَ فيه بالإيمانِ والعمل؛ فمن أحياك وأماتك قادرٌ على جمعك وبعثك؛ فأيقن بالبعثِ يقينًا جازمًا؛ ولا تكن من الأكثرين الذين لا يعلمون؛ فمن أيقن بالبعثِ عمل له، ومن جهله وأنكره غفل؛ فاجعل يقينك بالبعثِ حافزًا لك على الاستعدادِ بالعمل."}}]},{"title":"مُلكُ الله، ومشهدُ الأممِ الجاثيةِ إلى كتابها","range":[27,29],"theme":"تقريرُ مُلكِ الله للسماواتِ والأرض، وخسارةِ المبطلين يومَ الساعة، ومشهدِ كلِّ أمّةٍ جاثيةً تُدعى إلى كتابها لتُجزى بعملها، وأنّ كتابَ الأعمالِ ينطق بالحقِّ لأنّ الله كان يستنسخ ما يعملون","verses":[{"n":27,"reflection":{"text":"«ولله ملك السماوات والأرض ويوم تقوم الساعة يومئذ يخسر المبطلون» — ولله وحده ملكُ السماواتِ والأرض، ويومَ تقوم الساعةُ يخسر المبطلون؛ ففي هذا تقريرُ مُلكِ الله وخسارةِ أهلِ الباطل؛ فاعلم أنّ المُلكَ كلَّه لله، فاعمل للحقِّ لا للباطل، فأهلُ الباطلِ خاسرون يومَ القيامة، فكن من أهلِ الحقِّ الرابحين.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ للحقّ، وإدراكُ مُلكِ الله وخسارةِ المبطلين."},"action":{"text":"تأمّل تقريرَ مُلكِ الله وخسارةِ المبطلين: ولله وحده ملكُ السماواتِ والأرضِ وما فيهما، يتصرّف فيهما كيف يشاء؛ ويومَ تقوم الساعةُ ويُبعَث الخلقُ للحساب، يومئذٍ يخسر المبطلون — الذين أبطلوا أعمالهم بالكفرِ والشرك، أو عملوا الباطل — فيخسرون أنفسهم وأهليهم «ولله ملك السماوات والأرض ويوم تقوم الساعة يومئذ يخسر المبطلون»؛ ففي هذا تقريرُ أنّ المُلكَ كلَّه لله، وأنّ المبطلين هم الخاسرون يومَ القيامة؛ فالمُلكُ لله في الدنيا والآخرة؛ ويومَ القيامةِ يظهر خسرانُ أهلِ الباطل؛ فاعلم أنّ المُلكَ كلَّه لله وحده؛ لمن المُلكُ اليوم، لله الواحدِ القهّار؛ فاعمل للحقِّ لا للباطل؛ واجعل عملك موافقًا لشرعِ الله؛ فأهلُ الباطلِ — من الكفرِ والشركِ والبدعِ والمعاصي — خاسرون يومَ القيامة؛ قل هل ننبّئكم بالأخسرين أعمالًا، الذين ضلَّ سعيهم في الحياةِ الدنيا وهم يحسبون أنهم يحسنون صنعًا؛ فكن من أهلِ الحقِّ الرابحين، لا من أهلِ الباطلِ الخاسرين؛ فمن عمل بالحقِّ ربح، ومن عمل بالباطلِ خسر؛ فاجعل عملك حقًّا خالصًا لله؛ فبالعملِ بالحقِّ تربح يومَ يخسر المبطلون."}},{"n":28,"reflection":{"text":"«وترى كل أمة جاثية كل أمة تدعى إلى كتابها اليوم تجزون ما كنتم تعملون» — وترى كلَّ أمّةٍ جاثيةً على ركبها من هولِ الموقف، كلُّ أمّةٍ تُدعى إلى كتابِ أعمالها، اليومَ تُجزَون بما كنتم تعملون؛ ففي هذا مشهدُ الأممِ الجاثيةِ يومَ الحساب؛ فتصوّر هولَ ذلك اليومِ حيث تجثو الأممُ وتُدعى إلى كتبها، فاعمل صالحًا يُسِرّك في كتابك، فالجزاءُ على العمل، فأعدَّ لكتابك ما يسرّك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تصوّرُ هولِ الحساب، والعملُ الصالحُ ليُسِرَّ في كتابه."},"action":{"text":"تأمّل مشهدَ الأممِ الجاثية: وترى — أيها الناظرُ يومَ القيامة — كلَّ أمّةٍ من الأممِ جاثيةً على ركبها، بارِكةً من شدّةِ الهولِ وانتظارِ الحساب؛ كلُّ أمّةٍ تُدعى إلى كتابِ أعمالها الذي كتبته الملائكة؛ يُقال لهم: اليومَ تُجزَون بما كنتم تعملون في الدنيا من خيرٍ أو شر «وترى كل أمة جاثية كل أمة تدعى إلى كتابها اليوم تجزون ما كنتم تعملون»؛ ففي هذا مشهدٌ عظيمٌ مهيبٌ من مشاهدِ يومِ القيامة: الأممُ جاثيةٌ على الركبِ من الهول، تُدعى كلُّ أمّةٍ إلى كتابها لتُجزى بعملها؛ فمن هولِ ذلك اليومِ تجثو الأممُ على ركبها؛ وترى كلَّ أمّةٍ جاثية؛ فتصوّر هولَ ذلك الموقفِ العظيم؛ حيث تجثو الأممُ كلُّها، وتُدعى إلى كتبِ أعمالها؛ فاعمل عملًا صالحًا يُسِرّك حين تُدعى إلى كتابك؛ فأمّا من أوتي كتابه بيمينه فيقول هاؤمُ اقرؤوا كتابيه؛ فالجزاءُ يومئذٍ على العملِ بالعدل؛ فأعدَّ لكتابك ما يسرّك من العملِ الصالح؛ فمن عمل صالحًا سُرّ بكتابه، ومن أساء ساءه كتابه؛ فاجعل عملك في الدنيا ما يسرّك يومَ تُدعى إلى كتابك جاثيًا؛ فبالعملِ الصالحِ يُسِرّك كتابك وتفوز."}},{"n":29,"reflection":{"text":"«هذا كتابنا ينطق عليكم بالحق إنا كنا نستنسخ ما كنتم تعملون» — هذا كتابنا ينطق عليكم بالحقِّ بلا زيادةٍ ولا نقص، إنا كنا نأمر الملائكةَ بكتابةِ ما كنتم تعملون؛ ففي هذا بيانُ حفظِ الأعمالِ ونطقِ الكتابِ بالحق؛ فاعلم أنّ أعمالك محفوظةٌ مكتوبةٌ ستنطق بها كتبك، فراقب الله في عملك، فما من عملٍ إلا وهو مكتوبٌ عليك، فاحذر أن يُكتَب عليك سوء.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"مراقبةُ الله في العمل، وإدراكُ أنّ الأعمالَ محفوظةٌ مكتوبة."},"action":{"text":"تأمّل بيانَ حفظِ الأعمال: يُقال لهم: هذا كتابنا الذي كتبته الملائكةُ الحفظةُ ينطق عليكم بالحقِّ والصدق، بما عملتم بلا زيادةٍ ولا نقص؛ إنا كنا نستنسخ ونأمر الحفظةَ بكتابةِ ما كنتم تعملون في الدنيا؛ فكلُّ عملٍ مكتوبٌ محفوظ «هذا كتابنا ينطق عليكم بالحق إنا كنا نستنسخ ما كنتم تعملون»؛ ففي هذا بيانُ أنّ أعمالَ العبادِ محفوظةٌ مكتوبةٌ عند الله، تنطق بها كتبهم يومَ القيامةِ بالحق؛ فالملائكةُ تكتب كلَّ عمل؛ وينطق الكتابُ بالحقِّ لا يظلم أحدًا؛ فاعلم أنّ أعمالك كلَّها محفوظةٌ مكتوبةٌ عند الله؛ وإنّ عليكم لحافظين، كرامًا كاتبين، يعلمون ما تفعلون؛ ما يلفظ من قولٍ إلا لديه رقيبٌ عتيد؛ فراقب الله في كلِّ عملٍ وقولٍ وحركة؛ فما من عملٍ إلا وهو مكتوبٌ عليك في كتابك؛ ووُضِع الكتابُ فترى المجرمين مشفقين ممّا فيه، ويقولون يا ويلتنا ما لهذا الكتابِ لا يغادر صغيرةً ولا كبيرةً إلا أحصاها؛ فاحذر أن يُكتَب عليك سوءٌ تُفضَح به يومَ القيامة؛ فمن راقب الله في عمله كُتِب له خير، ومن غفل كُتِب عليه شر؛ فاجعل مراقبةَ الله نصبَ عينيك في كلِّ عمل؛ فبالمراقبةِ يُكتَب لك ما يسرّك."}}]},{"title":"جزاءُ الفريقين، وختامُ الحمدِ والكبرياءِ لله","range":[30,37],"theme":"دخولُ المؤمنين العاملين في رحمةِ الله وهو الفوزُ المبين، وتوبيخُ الكافرين المستكبرين وشكّهم في الساعةِ ونسيانهم لقاءَ يومهم واتّخاذهم آياتِ الله هزوًا واغترارهم بالدنيا فخلودهم في النار، وختمُ السورةِ بأنّ لله الحمدَ ربِّ العالمين وله الكبرياءُ وهو العزيزُ الحكيم","verses":[{"n":30,"reflection":{"text":"«فأما الذين آمنوا وعملوا الصالحات فيدخلهم ربهم في رحمته ذلك هو الفوز المبين» — أمّا الذين آمنوا وعملوا الصالحاتِ فيُدخِلهم ربّهم في رحمته (الجنّة)، ذلك هو الفوزُ الواضح؛ ففي هذا بيانُ جزاءِ المؤمنين؛ فاطلب هذا الفوزَ المبينَ بالإيمانِ والعملِ الصالح، فرحمةُ الله هي الفوز، فاعمل لتدخل في رحمةِ الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ الفوزِ المبينِ بالإيمانِ والعملِ الصالح."},"action":{"text":"تأمّل جزاءَ المؤمنين: فأمّا الذين آمنوا بالله ورسوله وعملوا الصالحاتِ من الطاعات، فيُدخِلهم ربّهم في رحمته — وهي الجنّةُ ورضوانه — فينالون رحمةَ الله وفضله؛ ذلك الدخولُ في الرحمةِ هو الفوزُ المبينُ الواضحُ الذي لا فوزَ بعده «فأما الذين آمنوا وعملوا الصالحات فيدخلهم ربهم في رحمته ذلك هو الفوز المبين»؛ ففي هذا بيانُ جزاءِ المؤمنين العاملين: دخولُ رحمةِ الله وجنّته، وهو الفوزُ الحقيقي؛ فمن آمن وعمل صالحًا أدخله الله في رحمته؛ فاطلب أنت هذا الفوزَ المبينَ بالإيمانِ الصادقِ والعملِ الصالح؛ فرحمةُ الله وجنّته هي الفوزُ الأكبر؛ فمن زُحزِح عن النارِ وأُدخِل الجنّةَ فقد فاز؛ ورحمتي وسعت كلَّ شيء، فسأكتبها للذين يتّقون؛ فاعمل لتدخل في رحمةِ الله وجنّته؛ فمن آمن وعمل صالحًا فاز الفوزَ المبين، ومن كفر وأساء خسر؛ فاجعل غايتك دخولَ رحمةِ الله؛ واعمل لها بالإيمانِ والعملِ الصالحِ مع رجاءِ رحمةِ الله؛ فبالإيمانِ والعملِ والرجاءِ تنال الفوزَ المبين."}},{"n":31,"reflection":{"text":"«وأما الذين كفروا أفلم تكن آياتي تتلى عليكم فاستكبرتم وكنتم قوما مجرمين» — وأمّا الذين كفروا فيُقال لهم توبيخًا: ألم تكن آياتي تُتلى عليكم فاستكبرتم عنها وكنتم قومًا مجرمين؟ ففي هذا توبيخُ الكافرين المستكبرين؛ فاحذر الاستكبارَ عن آياتِ الله والإجرام، فتواضع لآياتِ الله واتّبعها، فالاستكبارُ والإجرامُ سببُ العذاب.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التواضعُ لآياتِ الله واتّباعُها، وتركُ الاستكبارِ والإجرام."},"action":{"text":"تأمّل توبيخَ الكافرين: وأمّا الذين كفروا بالله وآياته فيُقال لهم يومَ القيامةِ توبيخًا وتقريعًا: ألم تكن آياتي تُتلى عليكم في الدنيا واضحةً بيّنة، فاستكبرتم عن الإيمانِ بها واتّباعها، وكنتم قومًا مجرمين مصرّين على الكفرِ والمعاصي؟ «وأما الذين كفروا أفلم تكن آياتي تتلى عليكم فاستكبرتم وكنتم قوما مجرمين»؛ ففي هذا توبيخٌ للكافرين على استكبارهم عن آياتِ الله وإجرامهم؛ فتُلِيت عليهم الآياتُ فاستكبروا وأجرموا، فاستحقّوا العذاب؛ فاحذر أنت الاستكبارَ عن آياتِ الله وشرعه؛ واحذر الإجرامَ والإصرارَ على الذنوب؛ فتواضع لآياتِ الله واقبلها واتّبعها؛ إنّ الذين يستكبرون عن عبادتي سيدخلون جهنّمَ داخرين؛ فالاستكبارُ عن الحقِّ والإجرامُ سببُ العذابِ والتوبيخ؛ فمن تواضع لآياتِ الله واتّبعها نجا وأُكرِم، ومن استكبر عنها وأجرم عُذّب ووُبِّخ؛ فاجعل موقفك من آياتِ الله التواضعَ والقبولَ والاتّباع؛ فبالتواضعِ لآياتِ الله والعملِ بها تنجو من التوبيخِ والعذاب."}},{"n":32,"reflection":{"text":"«وإذا قيل إن وعد الله حق والساعة لا ريب فيها قلتم ما ندري ما الساعة إن نظن إلا ظنا وما نحن بمستيقنين» — وإذا قيل لكم: إنّ وعدَ الله حقٌّ والساعةُ لا شكَّ فيها، قلتم: ما ندري ما الساعة، إن نظنُّ إلا ظنًّا وما نحن بموقنين؛ ففي هذا ذمُّ الشكِّ في الساعةِ والاكتفاءِ بالظن؛ فاحذر الشكَّ في وعدِ الله والساعة، فأيقن بهما يقينًا جازمًا، فالظنُّ لا يُغني عن الحق، فاطلب اليقينَ بالأدلّة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بوعدِ الله والساعة، وتركُ الشكِّ والظن."},"action":{"text":"تأمّل ذمَّ الشكِّ في الساعة: وإذا قيل لكم — أيها الكافرون — إنّ وعدَ الله بالبعثِ والجزاءِ حقٌّ لا شكَّ فيه، والساعةُ آتيةٌ لا ريبَ فيها، قلتم منكرين متردّدين: ما ندري ما الساعة وحقيقتها، إن نظنُّ إلا ظنًّا ضعيفًا، وما نحن بموقنين بها يقينًا جازمًا «وإذا قيل إن وعد الله حق والساعة لا ريب فيها قلتم ما ندري ما الساعة إن نظن إلا ظنا وما نحن بمستيقنين»؛ ففي هذا ذمُّ الكافرين على شكّهم في الساعةِ واكتفائهم بالظنِّ دون اليقين؛ فلم يجزموا بإنكارها بل شكّوا، ولم يبلغوا اليقين؛ فاحذر الشكَّ والتردّدَ في وعدِ الله وفي الساعة؛ فأيقن بوعدِ الله وبالساعةِ يقينًا جازمًا لا شكَّ فيه؛ فوعدُ الله حقٌّ والساعةُ آتيةٌ لا ريبَ فيها؛ إنّ الساعةَ آتيةٌ لا ريبَ فيها؛ فالظنُّ والشكُّ لا يُغنيان من الحقِّ شيئًا؛ وإنّ الظنَّ لا يُغني من الحقِّ شيئًا؛ فاطلب اليقينَ بوعدِ الله والساعةِ بالنظرِ في الأدلّةِ والبراهين؛ فمن أيقن بالساعةِ استعدّ لها، ومن شكّ فيها غفل وخسر؛ فاجعل يقينك بالبعثِ والساعةِ جازمًا؛ فباليقينِ تعمل للآخرةِ وتستعدّ للقاءِ الله."}},{"n":33,"reflection":{"text":"«وبدا لهم سيئات ما عملوا وحاق بهم ما كانوا به يستهزئون» — وظهر لهم قبحُ ما عملوا، وأحاط بهم العذابُ الذي كانوا به يستهزئون؛ ففي هذا بيانُ ظهورِ سيّئاتهم وإحاطةِ العذاب؛ فاحذر أن تظهر لك سيّئاتك يومَ القيامة، فاجتنب السيّئاتِ وتب منها، ولا تستهزئ بوعيدِ الله، فالاستهزاءُ يُحيق بصاحبه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اجتنابُ السيّئاتِ والتوبةُ منها، وتركُ الاستهزاءِ بوعيدِ الله."},"action":{"text":"تأمّل بيانَ عاقبةِ المستهزئين: وبدا وظهر لهؤلاء الكافرين يومَ القيامةِ قبحُ ما عملوا من السيّئاتِ والذنوب، بعد أن كانوا في غفلةٍ عنها؛ وحاق وأحاط بهم العذابُ الذي كانوا في الدنيا به يستهزئون ويكذّبون «وبدا لهم سيئات ما عملوا وحاق بهم ما كانوا به يستهزئون»؛ ففي هذا بيانُ أنّ سيّئاتِ الكافرين تظهر لهم يومَ القيامة، وأنّ العذابَ الذي استهزؤوا به يحيط بهم؛ فبدت لهم أعمالهم السيّئة، وأحاط بهم ما كذّبوا به؛ فاحذر أن تظهر لك سيّئاتك يومَ القيامةِ فتفتضح وتندم؛ فاجتنب السيّئاتِ والذنوب؛ وتب منها في الدنيا قبل أن تظهر لك في الآخرة؛ فالتوبةُ تمحو السيّئاتِ فلا تبدو يومَ القيامة؛ إلا من تاب وآمن وعمل صالحًا فأولئك يبدّل الله سيّئاتهم حسنات؛ ولا تستهزئ بوعيدِ الله وعذابه؛ فالاستهزاءُ بوعيدِ الله يُحيق بصاحبه ويحيط به؛ وحاق بهم ما كانوا به يستهزئون؛ فمن اجتنب السيّئاتِ وتاب منها نجا، ومن أصرّ عليها واستهزأ بالوعيدِ أحاط به العذاب؛ فاجعل همّك اجتنابَ السيّئاتِ والتوبةَ منها؛ فبالتوبةِ تُمحى سيّئاتك فلا تبدو، وتنجو من العذاب."}},{"n":34,"reflection":{"text":"«وقيل اليوم ننساكم كما نسيتم لقاء يومكم هذا ومأواكم النار وما لكم من ناصرين» — وقيل لهم: اليومَ نترككم في العذابِ كما تركتم العملَ للقاءِ يومكم هذا، ومأواكم النار، وما لكم من ناصرين؛ ففي هذا جزاءُ نسيانِ الآخرة؛ فاحذر أن تنسى الاستعدادَ للقاءِ الله فتُنسى في العذاب، فاعمل للقاءِ الله ولا تنسه، فمن نسي الآخرةَ نُسِي في النار.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ للقاءِ الله وعدمُ نسيانه، والحذرُ من نسيانِ الآخرة."},"action":{"text":"تأمّل جزاءَ نسيانِ الآخرة: وقيل للكافرين يومَ القيامةِ توبيخًا: اليومَ ننساكم ونترككم في العذابِ فلا نرحمكم، كما نسيتم أنتم في الدنيا الاستعدادَ للقاءِ يومكم هذا فلم تعملوا له، وأعرضتم عنه كأنكم لا تلاقونه؛ ومأواكم ومصيركم النارُ تُقيمون فيها، وما لكم من ناصرين ينصرونكم من عذابِ الله «وقيل اليوم ننساكم كما نسيتم لقاء يومكم هذا ومأواكم النار وما لكم من ناصرين»؛ ففي هذا بيانُ أنّ جزاءَ من نسي الآخرةَ في الدنيا أن يُنسى في العذابِ يومَ القيامة؛ فنسوا العملَ للقاءِ الله فتركهم الله في العذاب؛ نسوا الله فنسيهم؛ فاحذر أن تنسى الاستعدادَ للقاءِ الله والعملَ للآخرة، فتُنسى في نارِ جهنّم؛ فاعمل للقاءِ الله ولا تنسه ولا تغفل عنه؛ فمن كان يرجو لقاءَ الله فليعمل عملًا صالحًا؛ ولا تكونوا كالذين نسوا الله فأنساهم أنفسهم؛ فمن ذكر الآخرةَ وعمل لها نجا، ومن نسيها وأعرض عنها هلك؛ فاجعل لقاءَ الله نصبَ عينيك، واعمل له، ولا تنسه بزينةِ الدنيا؛ فبذكرِ الآخرةِ والعملِ لها تنجو من النار."}},{"n":35,"reflection":{"text":"«ذلكم بأنكم اتخذتم آيات الله هزوا وغرتكم الحياة الدنيا فاليوم لا يخرجون منها ولا هم يستعتبون» — ذلك العذابُ بسببِ أنكم اتّخذتم آياتِ الله هزوًا وغرّتكم الدنيا، فاليومَ لا يخرجون من النارِ ولا يُطلَب منهم إرضاءُ ربّهم؛ ففي هذا بيانُ سببِ العذابِ وأبديّته؛ فاحذر الاستهزاءَ بآياتِ الله والاغترارَ بالدنيا، فعظّم آياتِ الله ولا تغترّ بالدنيا، فهما سببُ الخلودِ في النار.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ آياتِ الله وعدمُ الاغترارِ بالدنيا، والحذرُ من الاستهزاء."},"action":{"text":"تأمّل بيانَ سببِ العذابِ وأبديّته: ذلكم العذابُ الذي حلَّ بكم بسببِ أنكم اتّخذتم آياتِ الله هزوًا وسخريةً في الدنيا، ولم تعظّموها؛ وغرّتكم الحياةُ الدنيا بزينتها وشهواتها فآثرتموها على الآخرة؛ فاليومَ لا يخرجون من النارِ أبدًا، ولا هم يُستعتَبون — أي لا يُطلَب منهم إرضاءُ ربّهم بالتوبةِ والعمل، لفواتِ أوانه «ذلكم بأنكم اتخذتم آيات الله هزوا وغرتكم الحياة الدنيا فاليوم لا يخرجون منها ولا هم يستعتبون»؛ ففي هذا بيانُ أنّ سببَ خلودهم في العذابِ أمران: الاستهزاءُ بآياتِ الله، والاغترارُ بالدنيا؛ وأنهم لا يخرجون من النارِ ولا تُقبَل منهم توبة؛ فاحذر هذين السببين: الاستهزاءَ بآياتِ الله، والاغترارَ بالحياةِ الدنيا؛ فعظّم آياتِ الله ووقّرها واتّبعها؛ ولا تغترّ بالدنيا وزينتها وشهواتها؛ فلا تغرّنّكم الحياةُ الدنيا ولا يغرّنّكم بالله الغرور؛ اعلموا أنما الحياةُ الدنيا لعبٌ ولهو؛ فالاستهزاءُ بآياتِ الله والاغترارُ بالدنيا سببُ الخلودِ في النار؛ فمن عظّم آياتِ الله وزهد في الدنيا نجا، ومن استهزأ بها واغترّ بالدنيا خلد في النار؛ فاجعل تعظيمَ آياتِ الله في قلبك، ولا تغترّ بالدنيا الفانية؛ فبتعظيمِ آياتِ الله والزهدِ في الدنيا تنجو من الخلودِ في النار."}},{"n":36,"reflection":{"text":"«فلله الحمد رب السماوات ورب الأرض رب العالمين» — فلله وحده الحمدُ الكامل، ربِّ السماواتِ وربِّ الأرضِ ربِّ العالمين جميعًا؛ ففي هذا إفرادُ الله بالحمدِ لربوبيّتِه الشاملة؛ فاحمد الله ربَّ العالمين على نعمه وربوبيّته، فالحمدُ كلُّه له، فاجعل حمدَ الله ديدنك في كلِّ حال.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إفرادُ الله بالحمدِ الكامل، وحمدُه على ربوبيّته ونعمه."},"action":{"text":"تأمّل إفرادَ الله بالحمد: فلله وحده الحمدُ الكاملُ المطلق، فهو ربُّ السماواتِ وربُّ الأرضِ ربُّ العالمين جميعًا، خالقهم ورازقهم ومدبّرهم؛ فمن كان بهذه الربوبيّةِ الشاملةِ استحقّ الحمدَ كلَّه «فلله الحمد رب السماوات ورب الأرض رب العالمين»؛ ففي هذا إفرادُ الله بالحمدِ الكامل، لأنه ربُّ كلِّ شيء؛ فلمّا كان ربَّ السماواتِ والأرضِ والعالمين، استحقّ الحمدَ المطلق؛ فاحمد الله ربَّ العالمين على نعمه العظيمةِ وربوبيّته الشاملة؛ الحمدُ لله ربِّ العالمين؛ وهو الله لا إله إلا هو له الحمدُ في الأولى والآخرة؛ فالحمدُ كلُّه لله على كلِّ حال؛ فاحمده على نعمه الظاهرةِ والباطنة؛ واحمده في السرّاءِ والضرّاء؛ فاجعل حمدَ الله ديدنك ودأبك في كلِّ حال؛ فمن حمد الله على نعمه زاده منها؛ فأكثِر من حمدِ الله والثناءِ عليه؛ فبالحمدِ تُشكَر النعمُ وتدوم وتزيد؛ فاجعل لسانك رطبًا بحمدِ الله وشكره."}},{"n":37,"reflection":{"text":"«وله الكبرياء في السماوات والأرض وهو العزيز الحكيم» — وله وحده العظمةُ والكبرياءُ في السماواتِ والأرض، وهو العزيزُ الحكيم؛ ففي هذا إفرادُ الله بالكبرياءِ والعظمة؛ فأفرد الله بالكبرياءِ والعظمة، وتواضع أنت لعظمته، فالكبرياءُ رداؤه لا يُنازَع فيها، فاخضع لعظمةِ الله وعزّته وحكمته.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إفرادُ الله بالكبرياءِ والعظمة، والتواضعُ لعظمته."},"action":{"text":"تأمّل إفرادَ الله بالكبرياء: وله وحده سبحانه الكبرياءُ والعظمةُ والجلالُ في السماواتِ والأرض، فهو المتعظّمُ عن كلِّ نقصٍ وسوء، المتعالي في عظمته وجلاله؛ وهو العزيزُ الذي لا يُغالَب، الحكيمُ في خلقه وشرعه وتدبيره «وله الكبرياء في السماوات والأرض وهو العزيز الحكيم»؛ ففي هذا إفرادُ الله بالكبرياءِ والعظمةِ في السماواتِ والأرض، وختمُ السورةِ بعزّته وحكمته؛ فالكبرياءُ والعظمةُ لله وحده؛ قال الله: الكبرياءُ ردائي والعظمةُ إزاري، فمن نازعني واحدًا منهما عذّبته؛ فأفرد الله بالكبرياءِ والعظمةِ والجلال؛ ولا تنازعه فيها بكبرٍ أو عظمةٍ في نفسك؛ فالكبرُ من صفةِ الله وحده، لا يليق بالعبدِ المخلوقِ الضعيف؛ فتواضع أنت لعظمةِ الله وكبريائه؛ واخضع لعزّته وحكمته؛ فمن تكبّر نازع الله في ردائه فأذلّه، ومن تواضع لله رفعه؛ لا يدخل الجنّةَ من كان في قلبه مثقالُ ذرّةٍ من كبر؛ فاجعل قلبك متواضعًا خاضعًا لعظمةِ الله وكبريائه؛ فهو العزيزُ الحكيم؛ فبالتواضعِ لله والخضوعِ لعظمته وعزّته وحكمته تُنال الرفعةُ والسعادة."}}]}],"coverage":{"covered":37,"total":37}};
